// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, address actor1, address actor2) public {
        vm.assume(ts > 0);
        vm.assume(actor1 != address(0) && actor1 != address(c));
        vm.assume(actor2 != address(0) && actor2 != address(c));
        vm.assume(actor1 != actor2);
        vm.warp(ts);

        vm.deal(actor1, 10 ether);
        vm.prank(actor1);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // second call in the SAME timestamp: must revert because
        // block.timestamp > pastBlockTime no longer holds
        vm.deal(actor2, 10 ether);
        vm.prank(actor2);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2);
    }
}
